from pathlib import Path
import json,collections
h=Path.home();c=h/'.codex';r=next((h/'.tokeneconomizer/repos').glob('eod*'))/'codex'
a=[json.loads(x) for x in (r/'ledger.jsonl').read_text(encoding='utf8').splitlines()]
by=collections.defaultdict(list)
for d in ('sessions','archived_sessions'):
 for p in (c/d).rglob('rollout-*.jsonl'):
  with p.open('rb') as f:m=json.loads(next(f)).get('payload',{})
  if m.get('cwd','').lower().endswith('eod charting platform'):by[m.get('id')].append((d,p))
for k,v in by.items():
 if len(v)>1 or v[0][0]=='archived_sessions' or k.startswith('01a1a02e'):
  for d,p in v:
   seen=[]
   with p.open('rb') as f:
    for ln in f:
     if b'"token_count"' not in ln:continue
     x=json.loads(ln);y=x.get('payload',{})
     i=y.get('info') if y.get('type')=='token_count' else None
     if i:seen.append((x.get('timestamp'),i['total_token_usage'],i.get('last_token_usage')))
   print(k[:8],d,len(seen),[(z[0],z[1].get('total_tokens'),(z[2] or {}).get('total_tokens')) for z in ([seen[0],seen[-1]] if seen else [])])
   if k.startswith('01a1a02e') and seen:print('last breakdown',seen[-1][1])
for x in a:
 if x['kind']=='session' and (x.get('error') or x['session_id'].startswith('01a1a02e')):
  print('ledger example',x['session_id'][:8],{k:x.get(k) for k in ('error','input_tokens','cache_read_input_tokens','output_tokens','requests','effective_tokens')},'matching rollout',bool(by.get(x['session_id'])))
print('injection file', (r/'injection.json').exists())
`)

