        sess = ctx.store.read(sess_name) or {}
        transcript = transcript_path or sess.get("transcript")
        record = {"kind": "session", "session_id": session_id, "host": ctx.host.name,
                  "repo": ctx.repo.label, "folded_at": time.time(),
                  "started": sess.get("started"), "ended": sess.get("ended"),
                  "shadow": ctx.config.shadow}
        workdir = tempfile.mkdtemp(prefix="te-fold-")
        try:
            usage = None
            if ctx.host.name == "codex":
                paths = _codex_transcripts(ctx, session_id, transcript)
                usage = codex_session_segments(paths)
                record["usage_status"] = usage["usage_status"]
                record["reasoning_output_tokens"] = usage["reasoning_output_tokens"]
                transcript = str(paths[0]) if paths else None
            transcript_error = usage and usage["usage_status"].startswith("transcript_")
            trace_path = (ctx.host.mechanism_trace(transcript, workdir)
                          if transcript and not transcript_error else None)
            try:
                prompts = (ctx.host.prompt_count(transcript)
                           if transcript and not transcript_error else None)
            except (OSError, ValueError):
                prompts = None
            record["prompts"] = prompts
            if not trace_path:
